import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    source = io.StringIO(raw_csv, newline="")
    reader = csv.reader(source, delimiter=",", quotechar='"', doublequote=True)
    columns = None
    rows = []

    while True:
        start = source.tell()
        line = source.readline()
        if not line:
            break

        # Check for file notes only at record boundaries, not inside quoted fields.
        stripped = line.lstrip(" \t")
        if stripped.startswith(("# ", "#\t")) or stripped.rstrip("\r\n") == "#":
            continue

        source.seek(start)
        record = next(reader)
        if not record:
            continue

        if columns is None:
            columns = record
        else:
            rows.append(record)

    if columns is None:
        return {"columns": [], "rows": []}

    width = max((len(row) for row in rows), default=len(columns))
    width = max(width, len(columns))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
